// th18_s5_w09: TH18 v1.00a Stage 5 midstage MainSub08.
// Source: st05.ecl.txt:1192-1197 MainSub08 -> enmCreate("GirlD03", 0,-48)
//         st05.ecl.txt:754-845 GirlD03()/GirlD03_at() (two big-star rings).
// Source %F0 = 3.883222 is set in MainSub08 before creation and inherited by GirlD03.
const TIME_LIMIT: int = 880;       // 120-frame activation buffer + 760-frame source span
const TH18_BIG_STAR_R: int = 720;  // source etSprite(0,23,3), native radius 7
const TH18_BIG_STAR_L: int = 736;  // source etSprite(1,24,2), native radius 7
const GOLDEN_BAM: int = 40503;     // %F0 = 3.883222 rad = 222.492 deg/tick as BAM

// Source EX slot: ANIM(a=1) retreat 4*speed = -2.4px (applied at fire position below),
// then WAIT(a=60), then VELTIME(a=60, r=4.0, s=keep birth angle).
// VELTIME raises scalar speed 0.6 -> 4.0 over 60 frames along the fixed angle.
xformdef SLOW_TO_FAST {
    wait(60);                // WAIT 60: motion continues, only the EX cursor stops
    set_accel(0.0566667fx);  // (4.0-0.6)/60 per frame; polar mode keeps the angle
    wait(60);
    set_accel(0fx);
}

sub fire_ring(base: int, n: int, shape: int, color: int) {
    // aim mode3 fixed ring: alpha + 2*pi*i/n. etCount(...,1) is one speed layer,
    // so etSpeed(0.6,1.6) uses only the first speed 0.6.
    for i in 0..n {
        var a: angle = (base + i * 65536 / n) as angle;
        _ = fire(shape, color,
                 $self_x - 2.4fx * cos(a), $self_y - 2.4fx * sin(a),
                 0.6fx, a, SLOW_TO_FAST, none);
    }
}

async sub shooter() {
    // GirlD03_at: wait(60); two et configs; %A/%B = RANDRAD; diffI(C,90,90,110,130);
    // wait: !E 5; !N 5; !H 4; !LO 3. First wave is immediate after the wait.
    // Config-time etAngle(0,20deg,0) is overwritten by etAngle(0,%A,...) before the
    // first etOn; its 0.6981317 (40deg) second angle is per-layer, unused with M=1.
    var rank: int = global(GVAR_RANK);
    var n: int = 4;        // etCount !E 1; !N 4; !H 4; !LO 4
    var count: int = 90;   // diffI
    var gap: int = 5;
    if rank == 0 { n = 1; }
    if rank == 2 { count = 110; gap = 4; }
    if rank == 3 { count = 130; gap = 3; }
    wait(60);
    var a: int = rand(65536) - 32768;  // %A = RANDRAD
    var b: int = rand(65536) - 32768;  // %B = RANDRAD
    for k in 0..count {
        // Same frame: etOn(0) ring then etOn(1) ring, then %A += F0 / %B -= F0.
        fire_ring(a, n, TH18_BIG_STAR_R, 3);
        fire_ring(b, n, TH18_BIG_STAR_L, 2);
        a = a + GOLDEN_BAM;
        b = b - GOLDEN_BAM;
        wait(gap);
    }
}

async sub girl() {
    // GirlD03: source setHurtbox(32), setHitbox(24); normal circle uses half.
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);    // moveVel(pi/2, 3.0)
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);  // moveVelTime(60, mode1=t^2, down, 0)
    spawn shooter();                         // source async: first runs one frame later
    wait(500);
    move_speed(120, 2fx, EASE_QUAD_IN);      // moveSpeedTime(120, mode1, 2.0)
    wait(60);
    loop { wait(1000); }                     // source goto/wait(1000) tail
}

async sub pattern() {
    wait(120); // activation buffer; MainSub08 itself is an instant spawn
    _ = spawn_enemy(0fx, -48fx, 5300, 0, 0, 0, girl);
    loop { wait(60); }
}

async sub director() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1); // control enemy at (0,0): no body collision
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, director);
    loop { wait(600); }
}
